import json
def solve(g):
    from collections import Counter
    H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in g]; seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                comp=[]; q=[(i,j)]; c=g[i][j]
                seen.add((i,j))
                while q:
                    a,b=q.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==c and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                for a,b in comp:
                    if r0<a<r1 and c0<b<c1: out[a][b]=2
    return out
